b = zlib.decompress(base64.b85decode(''.join(DATA.split()).encode('ascii')))
assert len(b) == 22669
assert hashlib.sha256(b).hexdigest() == '4b3321ecae7b2154be3c43a9a473aabf065533d40e81923d44d3a0003a260b13'
expected = {
 'lynx90_ward98_replay.py': '637653518da2f05fdc6faa1cc987884fc3d99402f0e9deec992e97a3b62a63db',
 'metric_screen.py': 'dd32b754f78627a6785b6b7d0674ce27476cb3dd02ffe5ada1bf68d892b30781'
}
files = json.loads(b)
assert set(files) == set(expected)
for name, text in files.items():
    raw = text.encode('utf-8')
    assert hashlib.sha256(raw).hexdigest() == expected[name]
    Path(name).write_bytes(raw)
    print(name, len(raw), expected[name])
